use crate::event::{Event, EventType};
use crate::task::TaskState;

/// A mutex with optional priority inheritance (PI).
///
/// For EDF scheduling, PI is implemented as *deadline inheritance*:
/// when a high-priority (earlier-deadline) task blocks on this mutex,
/// the owner's effective_deadline is reduced to the blocker's deadline,
/// allowing the owner to preempt medium-priority tasks.
pub struct PiMutex {
    pub id: usize,
    pub owner: Option<usize>,
    pub wait_queue: Vec<usize>,
    pub pi_enabled: bool,
}

impl PiMutex {
    pub fn new(id: usize, pi_enabled: bool) -> Self {
        PiMutex {
            id,
            owner: None,
            wait_queue: Vec::new(),
            pi_enabled,
        }
    }

    /// Try to acquire the mutex for `task_id`.
    /// Returns `true` if acquired immediately, `false` if blocked.
    pub fn try_lock(
        &mut self,
        task_id: usize,
        tasks: &mut [Task],
        events: &mut Vec<Event>,
        current_time: u32,
    ) -> bool {
        match self.owner {
            None => {
                self.owner = Some(task_id);
                tasks[task_id].held_mutex = Some(self.id);
                events.push(Event::new(
                    current_time,
                    task_id,
                    EventType::MutexAcquired(self.id),
                ));
                true
            }
            Some(_) => {
                // Block the requesting task
                tasks[task_id].state = TaskState::Blocked;
                tasks[task_id].blocked_at = Some(current_time);
                self.wait_queue.push(task_id);
                events.push(Event::new(
                    current_time,
                    task_id,
                    EventType::Blocked(self.id),
                ));

                // Apply priority inheritance
                if self.pi_enabled {
                    self.apply_pi(tasks, events, current_time);
                }
                false
            }
        }
    }

    /// Release the mutex held by `task_id`. Wakes up the highest-priority waiter.
    /// Returns the woken task ID, if any.
    pub fn unlock(
        &mut self,
        task_id: usize,
        tasks: &mut [Task],
        events: &mut Vec<Event>,
        current_time: u32,
    ) -> Option<usize> {
        if self.owner != Some(task_id) {
            return None;
        }

        // Restore owner's effective deadline
        let old_eff = tasks[task_id].effective_deadline;
        let original = tasks[task_id].absolute_deadline;
        if old_eff < original {
            tasks[task_id].effective_deadline = original;
            events.push(Event::new(
                current_time,
                task_id,
                EventType::PriorityRestored {
                    original_deadline: original,
                },
            ));
        }

        tasks[task_id].held_mutex = None;
        self.owner = None;
        events.push(Event::new(
            current_time,
            task_id,
            EventType::MutexReleased(self.id),
        ));

        // Wake up the waiter with the earliest effective deadline
        if let Some(&best_tid) = self
            .wait_queue
            .iter()
            .min_by_key(|&&tid| tasks[tid].effective_deadline)
        {
            self.wait_queue.retain(|&tid| tid != best_tid);

            // Transfer ownership
            self.owner = Some(best_tid);
            tasks[best_tid].held_mutex = Some(self.id);
            tasks[best_tid].state = TaskState::Ready;

            events.push(Event::new(
                current_time,
                best_tid,
                EventType::MutexAcquired(self.id),
            ));
            events.push(Event::new(
                current_time,
                best_tid,
                EventType::Unblocked(self.id),
            ));

            Some(best_tid)
        } else {
            None
        }
    }

    /// Priority inheritance: boost the owner's effective deadline
    /// to the minimum of its current value and all waiters' deadlines.
    fn apply_pi(
        &mut self,
        tasks: &mut [Task],
        events: &mut Vec<Event>,
        current_time: u32,
    ) {
        if let Some(owner_id) = self.owner {
            let min_waiter_deadline = self
                .wait_queue
                .iter()
                .map(|&tid| tasks[tid].effective_deadline)
                .min()
                .unwrap_or(u32::MAX);

            if min_waiter_deadline < tasks[owner_id].effective_deadline {
                tasks[owner_id].effective_deadline = min_waiter_deadline;
                events.push(Event::new(
                    current_time,
                    owner_id,
                    EventType::PriorityInherited {
                        new_effective_deadline: min_waiter_deadline,
                    },
                ));
            }
        }
    }
}

use crate::event::{Event, EventType};
use crate::kernel::Kernel;
use crate::mutex::PiMutex;
use crate::task::{Segment, Task};
use rand::SeedableRng;
use rand::Rng;
use rand::rngs::StdRng;

// ---------------------------------------------------------------------------
// Result types
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub struct SingleRunResult {
    pub pi_enabled: bool,
    /// H task blocking duration (ticks from block to unblock).
    pub h_inversion_duration: Option<u32>,
    /// H task response time (release → completion) for first job.
    pub h_response_time: Option<u32>,
    /// Whether H missed its deadline in the first job.
    pub h_deadline_missed: bool,
    /// Total deadline misses across all tasks.
    pub total_deadline_misses: u32,
    /// Per-task deadline misses: (task_name, misses).
    pub per_task_misses: Vec<(String, u32)>,
    /// Per-task average response time.
    pub per_task_avg_response: Vec<(String, f64)>,
    /// Full event log (kept for detailed output on first run).
    pub events: Vec<Event>,
    /// Timeline: (tick, running_task_name) for visualization.
    pub timeline: Vec<(u32, String)>,
}

#[derive(Debug, Clone)]
pub struct BatchResult {
    pub pi_enabled: bool,
    pub n_runs: usize,
    pub h_inversion_durations: Vec<Option<u32>>,
    pub h_response_times: Vec<Option<u32>>,
    pub h_deadline_miss_count: u32,
    pub total_deadline_misses: Vec<u32>,
    pub first_run_events: Vec<Event>,
    pub first_run_timeline: Vec<(u32, String)>,
}

impl BatchResult {
    pub fn h_inversion_stats(&self) -> Option<Stats> {
        let vals: Vec<u32> = self.h_inversion_durations.iter().filter_map(|&x| x).collect();
        Stats::from_slice(&vals)
    }

    pub fn h_response_stats(&self) -> Option<Stats> {
        let vals: Vec<u32> = self.h_response_times.iter().filter_map(|&x| x).collect();
        Stats::from_slice(&vals)
    }

    pub fn total_misses_stats(&self) -> Option<Stats> {
        Stats::from_slice(&self.total_deadline_misses)
    }
}

#[derive(Debug, Clone)]
pub struct Stats {
    pub mean: f64,
    pub variance: f64,
    pub std_dev: f64,
    pub min: f64,
    pub max: f64,
}

impl Stats {
    pub fn from_slice(vals: &[u32]) -> Option<Stats> {
        if vals.is_empty() {
            return None;
        }
        let n = vals.len() as f64;
        let mean = vals.iter().sum::<u32>() as f64 / n;
        let variance = if vals.len() > 1 {
            vals.iter().map(|&x| (x as f64 - mean).powi(2)).sum::<f64>() / n
        } else {
            0.0
        };
        Some(Stats {
            mean,
            variance,
            std_dev: variance.sqrt(),
            min: vals.iter().map(|&x| x as f64).fold(f64::INFINITY, f64::min),
            max: vals.iter().map(|&x| x as f64).fold(f64::NEG_INFINITY, f64::max),
        })
    }
}

// ---------------------------------------------------------------------------
// Scenario configuration
// ---------------------------------------------------------------------------

/// Classic priority inversion scenario with 3 tasks and 1 shared mutex.
///
/// Task L (Low):     period=200, deadline=200, wcet=40, offset=0
///   [Compute(5)] → [CriticalSection(20, mutex=0)] → [Compute(15)]
///
/// Task H (High):    period=60,  deadline=60,  wcet=20, offset=10
///   [Compute(5)] → [CriticalSection(5, mutex=0)] → [Compute(10)]
///
/// Task M (Medium):  period=100, deadline=100, wcet=30, offset=15
///   [Compute(30)]
fn build_tasks() -> Vec<Task> {
    let task_l = Task::new(
        0,
        "L",
        3, // lowest base priority
        200,
        200,
        vec![
            Segment::Compute(5),
            Segment::CriticalSection {
                duration: 20,
                mutex_id: 0,
            },
            Segment::Compute(15),
        ],
        0, // first release at t=0
    );

    let task_h = Task::new(
        1,
        "H",
        1, // highest base priority
        60,
        60,
        vec![
            Segment::Compute(5),
            Segment::CriticalSection {
                duration: 5,
                mutex_id: 0,
            },
            Segment::Compute(10),
        ],
        10, // first release at t=10
    );

    let task_m = Task::new(
        2,
        "M",
        2, // medium base priority
        100,
        100,
        vec![Segment::Compute(30)],
        15, // first release at t=15
    );

    vec![task_l, task_h, task_m]
}

fn build_tasks_with_jitter(jitter_pct: f64, seed: u64) -> Vec<Task> {
    let mut rng: StdRng = SeedableRng::seed_from_u64(seed);
    let base = build_tasks();
    base.into_iter()
        .map(|t| t.with_jitter(jitter_pct, &mut || rng.gen::<f64>()))
        .collect()
}

// ---------------------------------------------------------------------------
// Single run
// ---------------------------------------------------------------------------

pub fn run_single(pi_enabled: bool, sim_duration: u32) -> SingleRunResult {
    run_single_with_jitter(pi_enabled, sim_duration, 0.0, 0)
}

pub fn run_single_with_jitter(
    pi_enabled: bool,
    sim_duration: u32,
    jitter_pct: f64,
    seed: u64,
) -> SingleRunResult {
    let tasks = if jitter_pct > 0.0 {
        build_tasks_with_jitter(jitter_pct, seed)
    } else {
        build_tasks()
    };

    let mutex = PiMutex::new(0, pi_enabled);
    let mut kernel = Kernel::new(tasks, vec![mutex], sim_duration);
    kernel.run();

    let events: Vec<Event> = kernel.events.clone();
    let tasks = &kernel.tasks;

    // Build timeline: find which task was running at each tick
    let mut timeline = Vec::new();
    let mut current_runner: Option<String> = None;
    for ev in &events {
        match &ev.event_type {
            EventType::Scheduled => {
                current_runner = Some(kernel.task_name(ev.task_id).to_string());
                timeline.push((ev.time, current_runner.clone().unwrap()));
            }
            EventType::Preempted | EventType::Blocked(_) => {
                current_runner = None;
            }
            _ => {}
        }
    }

    // Measure H's inversion duration: time from Blocked to Unblocked
    let mut h_block_time: Option<u32> = None;
    let mut h_unblock_time: Option<u32> = None;
    for ev in &events {
        if ev.task_id == 1 {
            // H is task_id=1
            match &ev.event_type {
                EventType::Blocked(_) => h_block_time = Some(ev.time),
                EventType::Unblocked(_) => h_unblock_time = Some(ev.time),
                _ => {}
            }
        }
    }
    let h_inversion_duration = match (h_block_time, h_unblock_time) {
        (Some(b), Some(u)) => Some(u - b),
        _ => None,
    };

    // H's response time (first job)
    let h_task = &tasks[1];
    let h_response_time = h_task.response_times.first().copied();
    let h_deadline_missed = h_task.deadline_misses > 0;

    // Total deadline misses
    let total_deadline_misses: u32 = tasks.iter().map(|t| t.deadline_misses).sum();

    // Per-task stats
    let per_task_misses: Vec<(String, u32)> = tasks
        .iter()
        .map(|t| (t.name.clone(), t.deadline_misses))
        .collect();

    let per_task_avg_response: Vec<(String, f64)> = tasks
        .iter()
        .map(|t| {
            let avg = if t.response_times.is_empty() {
                0.0
            } else {
                t.response_times.iter().sum::<u32>() as f64 / t.response_times.len() as f64
            };
            (t.name.clone(), avg)
        })
        .collect();

    SingleRunResult {
        pi_enabled,
        h_inversion_duration,
        h_response_time,
        h_deadline_missed,
        total_deadline_misses,
        per_task_misses,
        per_task_avg_response,
        events,
        timeline,
    }
}

// ---------------------------------------------------------------------------
// Batch runs
// ---------------------------------------------------------------------------

pub fn run_batch(n_runs: usize, pi_enabled: bool, sim_duration: u32) -> BatchResult {
    run_batch_with_jitter(n_runs, pi_enabled, sim_duration, 0.0)
}

pub fn run_batch_with_jitter(
    n_runs: usize,
    pi_enabled: bool,
    sim_duration: u32,
    jitter_pct: f64,
) -> BatchResult {
    let mut h_inversion_durations = Vec::with_capacity(n_runs);
    let mut h_response_times = Vec::with_capacity(n_runs);
    let mut total_deadline_misses = Vec::with_capacity(n_runs);
    let mut first_run_events = Vec::new();
    let mut first_run_timeline = Vec::new();
    let mut h_deadline_miss_count = 0u32;

    for i in 0..n_runs {
        let seed = if jitter_pct > 0.0 { (i + 1) as u64 * 7919 } else { 0 };
        let result = run_single_with_jitter(pi_enabled, sim_duration, jitter_pct, seed);

        if i == 0 {
            first_run_events = result.events;
            first_run_timeline = result.timeline;
        }

        h_inversion_durations.push(result.h_inversion_duration);
        h_response_times.push(result.h_response_time);
        total_deadline_misses.push(result.total_deadline_misses);
        if result.h_deadline_missed {
            h_deadline_miss_count += 1;
        }
    }

    BatchResult {
        pi_enabled,
        n_runs,
        h_inversion_durations,
        h_response_times,
        h_deadline_miss_count,
        total_deadline_misses,
        first_run_events,
        first_run_timeline,
    }
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

pub fn print_timeline(timeline: &[(u32, String)], max_ticks: u32) {
    println!("\n  Execution Timeline (first {} ticks):", max_ticks.min(timeline.len() as u32));
    println!("  {}", "-".repeat(72));

    // Group consecutive ticks by task
    let mut groups: Vec<(String, u32, u32)> = Vec::new(); // (task, start, end)
    for &(tick, ref task) in timeline.iter() {
        if tick > max_ticks {
            break;
        }
        if let Some(last) = groups.last_mut() {
            if last.0 == task && last.2 + 1 == tick {
                last.2 = tick;
            } else {
                groups.push((task.clone(), tick, tick));
            }
        } else {
            groups.push((task.clone(), tick, tick));
        }
    }

    for (task, start, end) in &groups {
        let bar_len = (*end - *start + 1) as usize;
        let bar: String = if task == "H" {
            "H".repeat(bar_len)
        } else if task == "M" {
            "M".repeat(bar_len)
        } else {
            "L".repeat(bar_len)
        };
        println!("  t={:>3}-{:<3} {} ({})", start, end, bar, task);
    }
    println!("  {}", "-".repeat(72));
}

pub fn print_events(events: &[Event], task_names: &[&str], max_events: usize) {
    println!("\n  Key Events:");
    println!("  {:>5}  {:>4}  {:>14}  {}", "Time", "Task", "Event", "Detail");
    println!("  {}", "-".repeat(60));

    let mut count = 0;
    for ev in events {
        if count >= max_events {
            println!("  ... ({} more events)", events.len() - max_events);
            break;
        }
        let name = task_names.get(ev.task_id).unwrap_or(&"?");
        let (ev_name, detail) = match &ev.event_type {
            EventType::Released => ("RELEASED", "".into()),
            EventType::Scheduled => ("SCHEDULED", "".into()),
            EventType::Preempted => ("PREEMPTED", "".into()),
            EventType::Blocked(mid) => ("BLOCKED", format!("mutex={}", mid)),
            EventType::Unblocked(mid) => ("UNBLOCKED", format!("mutex={}", mid)),
            EventType::MutexAcquired(mid) => ("LOCK_ACQ", format!("mutex={}", mid)),
            EventType::MutexReleased(mid) => ("LOCK_REL", format!("mutex={}", mid)),
            EventType::JobCompleted { response_time } => {
                ("JOB_DONE", format!("resp_time={}", response_time))
            }
            EventType::DeadlineMissed {
                deadline,
                completed_at,
            } => (
                "DEADLINE_MISS",
                format!("deadline={}, completed={}", deadline, completed_at),
            ),
            EventType::PriorityInherited {
                new_effective_deadline,
            } => (
                "PI_BOOST",
                format!("eff_deadline={}", new_effective_deadline),
            ),
            EventType::PriorityRestored {
                original_deadline,
            } => (
                "PI_RESTORE",
                format!("deadline={}", original_deadline),
            ),
        };

        // Skip redundant SCHEDULED events for readability
        if matches!(ev.event_type, EventType::Scheduled) {
            continue;
        }

        println!("  {:>5}  {:>4}  {:>14}  {}", ev.time, name, ev_name, detail);
        count += 1;
    }
}

pub fn print_batch_summary(label: &str, result: &BatchResult) {
    println!("\n{}", "=".repeat(70));
    println!("  {} (PI {})", label, if result.pi_enabled { "ON" } else { "OFF" });
    println!("  Runs: {}", result.n_runs);
    println!("{}", "=".repeat(70));

    if let Some(stats) = result.h_inversion_stats() {
        println!("  H Inversion Duration: mean={:.2}  std_dev={:.4}  min={:.0}  max={:.0}",
            stats.mean, stats.std_dev, stats.min, stats.max);
    } else {
        println!("  H Inversion Duration: N/A (no inversion detected)");
    }

    if let Some(stats) = result.h_response_stats() {
        println!("  H Response Time:      mean={:.2}  std_dev={:.4}  min={:.0}  max={:.0}",
            stats.mean, stats.std_dev, stats.min, stats.max);
    }

    if let Some(stats) = result.total_misses_stats() {
        println!("  Total Deadline Misses: mean={:.2}  std_dev={:.4}  min={:.0}  max={:.0}",
            stats.mean, stats.std_dev, stats.min, stats.max);
    }

    println!("  H Deadline Miss Rate:  {}/{} runs ({:.1}%)",
        result.h_deadline_miss_count, result.n_runs,
        result.h_deadline_miss_count as f64 / result.n_runs as f64 * 100.0);
}

pub fn print_comparison(no_pi: &BatchResult, with_pi: &BatchResult) {
    println!("\n{}", "=".repeat(70));
    println!("  COMPARISON: PI OFF vs PI ON");
    println!("{}", "=".repeat(70));
    println!("  {:>25}  {:>12}  {:>12}", "Metric", "PI OFF", "PI ON");
    println!("  {}", "-".repeat(52));

    let none = |s: Option<Stats>| -> String {
        match s {
            Some(st) => format!("{:.1} +/- {:.2}", st.mean, st.std_dev),
            None => "N/A".into(),
        }
    };

    println!("  {:>25}  {:>12}  {:>12}",
        "H Inversion Duration",
        none(no_pi.h_inversion_stats()),
        none(with_pi.h_inversion_stats()));

    println!("  {:>25}  {:>12}  {:>12}",
        "H Response Time",
        none(no_pi.h_response_stats()),
        none(with_pi.h_response_stats()));

    println!("  {:>25}  {:>12}  {:>12}",
        "Total Deadline Misses",
        none(no_pi.total_misses_stats()),
        none(with_pi.total_misses_stats()));

    println!("  {:>25}  {:>12}  {:>12}",
        "H Deadline Miss Rate",
        format!("{:.0}%", no_pi.h_deadline_miss_count as f64 / no_pi.n_runs as f64 * 100.0),
        format!("{:.0}%", with_pi.h_deadline_miss_count as f64 / with_pi.n_runs as f64 * 100.0));

    println!();
}

