171	pub fn run_single_with_jitter(
172	    pi_enabled: bool,
173	    sim_duration: u32,
174	    jitter_pct: f64,
175	    seed: u64,
176	) -> SingleRunResult {
177	    let tasks = if jitter_pct > 0.0 {
178	        build_tasks_with_jitter(jitter_pct, seed)
179	    } else {
180	        build_tasks()
181	    };
182	
183	    let mutex = PiMutex::new(0, pi_enabled);
184	    let mut kernel = Kernel::new(tasks, vec![mutex], sim_duration);
185	    kernel.run();
186	
187	    let events: Vec<Event> = kernel.events.clone();
188	    let tasks = &kernel.tasks;
189	
190	    // Build timeline: find which task was running at each tick
191	    let mut timeline = Vec::new();
192	    let mut current_runner: Option<String> = None;
193	    for ev in &events {
194	        match &ev.event_type {
195	            EventType::Scheduled => {
196	                current_runner = Some(kernel.task_name(ev.task_id).to_string());
197	                timeline.push((ev.time, current_runner.clone().unwrap()));
198	            }
199	            EventType::Preempted | EventType::Blocked(_) => {
200	                current_runner = None;
201	            }
202	            _ => {}
203	        }
204	    }
205	
206	    // Measure H's inversion duration: time from Blocked to Unblocked
207	    let mut h_block_time: Option<u32> = None;
208	    let mut h_unblock_time: Option<u32> = None;
209	    for ev in &events {
210	        if ev.task_id == 1 {
211	            // H is task_id=1
212	            match &ev.event_type {
213	                EventType::Blocked(_) => h_block_time = Some(ev.time),
214	                EventType::Unblocked(_) => h_unblock_time = Some(ev.time),
215	                _ => {}
216	            }
217	        }
218	    }
219	    let h_inversion_duration = match (h_block_time, h_unblock_time) {
220	        (Some(b), Some(u)) => Some(u - b),
221	        _ => None,
222	    };
223	
224	    // H's response time (first job)
225	    let h_task = &tasks[1];
226	    let h_response_time = h_task.response_times.first().copied();
227	    let h_deadline_missed = h_task.deadline_misses > 0;
228	
229	    // Total deadline misses
230	    let total_deadline_misses: u32 = tasks.iter().map(|t| t.deadline_misses).sum();
231	
232	    // Per-task stats
233	    let per_task_misses: Vec<(String, u32)> = tasks
234	        .iter()
235	        .map(|t| (t.name.clone(), t.deadline_misses))
236	        .collect();
237	
238	    let per_task_avg_response: Vec<(String, f64)> = tasks
239	        .iter()
240	        .map(|t| {
241	            let avg = if t.response_times.is_empty() {
242	                0.0
243	            } else {
244	                t.response_times.iter().sum::<u32>() as f64 / t.response_times.len() as f64
245	            };
246	            (t.name.clone(), avg)
247	        })
248	        .collect();
249	
250	    SingleRunResult {
251	        pi_enabled,
252	        h_inversion_duration,
253	        h_response_time,
254	        h_deadline_missed,
255	        total_deadline_misses,
256	        per_task_misses,
257	        per_task_avg_response,
258	        events,
259	        timeline,
260	    }
261	}
