271	pub fn run_batch_with_jitter(
272	    n_runs: usize,
273	    pi_enabled: bool,
274	    sim_duration: u32,
275	    jitter_pct: f64,
276	) -> BatchResult {
277	    let mut h_inversion_durations = Vec::with_capacity(n_runs);
278	    let mut h_response_times = Vec::with_capacity(n_runs);
279	    let mut total_deadline_misses = Vec::with_capacity(n_runs);
280	    let mut first_run_events = Vec::new();
281	    let mut first_run_timeline = Vec::new();
282	    let mut h_deadline_miss_count = 0u32;
283	
284	    for i in 0..n_runs {
285	        let seed = if jitter_pct > 0.0 { (i + 1) as u64 * 7919 } else { 0 };
286	        let result = run_single_with_jitter(pi_enabled, sim_duration, jitter_pct, seed);
287	
288	        if i == 0 {
289	            first_run_events = result.events;
290	            first_run_timeline = result.timeline;
291	        }
292	
293	        h_inversion_durations.push(result.h_inversion_duration);
294	        h_response_times.push(result.h_response_time);
295	        total_deadline_misses.push(result.total_deadline_misses);
296	        if result.h_deadline_missed {
297	            h_deadline_miss_count += 1;
298	        }
299	    }
300	
301	    BatchResult {
302	        pi_enabled,
303	        n_runs,
304	        h_inversion_durations,
305	        h_response_times,
306	        h_deadline_miss_count,
307	        total_deadline_misses,
