317	pub fn print_timeline(timeline: &[(u32, String)], max_ticks: u32) {
318	    println!("\n  Execution Timeline (first {} ticks):", max_ticks.min(timeline.len() as u32));
319	    println!("  {}", "-".repeat(72));
320	
321	    // Group consecutive ticks by task
322	    let mut groups: Vec<(String, u32, u32)> = Vec::new(); // (task, start, end)
323	    for &(tick, ref task) in timeline.iter() {
324	        if tick > max_ticks {
325	            break;
326	        }
327	        if let Some(last) = groups.last_mut() {
328	            if last.0 == *task && last.2 + 1 == tick {
329	                last.2 = tick;
330	            } else {
331	                groups.push((task.clone(), tick, tick));
332	            }
333	        } else {
334	            groups.push((task.clone(), tick, tick));
335	        }
336	    }
337	
338	    for (task, start, end) in &groups {
339	        let bar_len = (*end - *start + 1) as usize;
340	        let bar: String = if task == "H" {
341	            "H".repeat(bar_len)
342	        } else if task == "M" {
343	            "M".repeat(bar_len)
344	        } else {
345	            "L".repeat(bar_len)
346	        };
347	        println!("  t={:>3}-{:<3} {} ({})", start, end, bar, task);
348	    }
349	    println!("  {}", "-".repeat(72));
350	}
