352	pub fn print_events(events: &[Event], task_names: &[&str], max_events: usize) {
353	    println!("\n  Key Events:");
354	    println!("  {:>5}  {:>4}  {:>14}  {}", "Time", "Task", "Event", "Detail");
355	    println!("  {}", "-".repeat(60));
356	
357	    let mut count = 0;
358	    for ev in events {
359	        if count >= max_events {
360	            println!("  ... ({} more events)", events.len() - max_events);
361	            break;
362	        }
363	        let name = task_names.get(ev.task_id).unwrap_or(&"?");
364	        let (ev_name, detail) = match &ev.event_type {
365	            EventType::Released => ("RELEASED", "".into()),
366	            EventType::Scheduled => ("SCHEDULED", "".into()),
367	            EventType::Preempted => ("PREEMPTED", "".into()),
368	            EventType::Blocked(mid) => ("BLOCKED", format!("mutex={}", mid)),
369	            EventType::Unblocked(mid) => ("UNBLOCKED", format!("mutex={}", mid)),
370	            EventType::MutexAcquired(mid) => ("LOCK_ACQ", format!("mutex={}", mid)),
371	            EventType::MutexReleased(mid) => ("LOCK_REL", format!("mutex={}", mid)),
372	            EventType::JobCompleted { response_time } => {
373	                ("JOB_DONE", format!("resp_time={}", response_time))
374	            }
375	            EventType::DeadlineMissed {
376	                deadline,
377	                completed_at,
378	            } => (
379	                "DEADLINE_MISS",
380	                format!("deadline={}, completed={}", deadline, completed_at),
381	            ),
382	            EventType::PriorityInherited {
383	                new_effective_deadline,
384	            } => (
385	                "PI_BOOST",
386	                format!("eff_deadline={}", new_effective_deadline),
387	            ),
388	            EventType::PriorityRestored {
389	                original_deadline,
390	            } => (
391	                "PI_RESTORE",
392	                format!("deadline={}", original_deadline),
393	            ),
394	        };
395	
396	        // Skip redundant SCHEDULED events for readability
397	        if matches!(ev.event_type, EventType::Scheduled) {
398	            continue;
399	        }
400	
401	        println!("  {:>5}  {:>4}  {:>14}  {}", ev.time, name, ev_name, detail);
402	        count += 1;
403	    }
404	}
