#[derive(Debug, Clone)]
pub struct SingleRunResult {
    pub pi_enabled: bool,
    /// H task blocking duration (ticks from block to unblock).
    pub h_inversion_duration: Option<u32>,
    /// H task response time (release → completion) for first job.
    pub h_response_time: Option<u32>,
    /// Whether H missed its deadline in the first job.
    pub h_deadline_missed: bool,
    /// Total deadline misses across all tasks.
    pub total_deadline_misses: u32,
    /// Per-task deadline misses: (task_name, misses).
    pub per_task_misses: Vec<(String, u32)>,
    /// Per-task average response time.
    pub per_task_avg_response: Vec<(String, f64)>,
    /// Full event log.
    pub events: Vec<Event>,
    /// Per-tick runner: task_names[task_id] for each tick.
    pub tick_runner: Vec<Option<usize>>,
}

#[derive(Debug, Clone)]
pub struct BatchResult {
    pub pi_enabled: bool,
    pub n_runs: usize,
    pub h_inversion_durations: Vec<Option<u32>>,
    pub h_response_times: Vec<Option<u32>>,
    pub h_deadline_miss_count: u32,
    pub total_deadline_misses: Vec<u32>,
    pub first_run_events: Vec<Event>,
    pub first_run_tick_runner: Vec<Option<usize>>,
}

impl BatchResult {
    pub fn h_inversion_stats(&self) -> Option<Stats> {
        let vals: Vec<u32> = self.h_inversion_durations.iter().filter_map(|&x| x).collect();
        Stats::from_slice(&vals)
    }

    pub fn h_response_stats(&self) -> Option<Stats> {
        let vals: Vec<u32> = self.h_response_times.iter().filter_map(|&x| x).collect();
        Stats::from_slice(&vals)
    }

    pub fn total_misses_stats(&self) -> Option<Stats> {
        Stats::from_slice(&self.total_deadline_misses)
    }
}

#[derive(Debug, Clone)]
pub struct Stats {
    pub mean: f64,
    pub variance: f64,
    pub std_dev: f64,
    pub min: f64,
    pub max: f64,
}

impl Stats {
    pub fn from_slice(vals: &[u32]) -> Option<Stats> {
        if vals.is_empty() {
            return None;
        }
        let n = vals.len() as f64;
        let mean = vals.iter().sum::<u32>() as f64 / n;
        let variance = if vals.len() > 1 {
            vals.iter().map(|&x| (x as f64 - mean).powi(2)).sum::<f64>() / n
        } else {
            0.0
        };
        Some(Stats {
            mean,
            variance,
            std_dev: variance.sqrt(),
            min: vals.iter().map(|&x| x as f64).fold(f64::INFINITY, f64::min),
            max: vals.iter().map(|&x| x as f64).fold(f64::NEG_INFINITY, f64::max),
        })
    }
}

// ---------------------------------------------------------------------------
// Scenario configuration
// ---------------------------------------------------------------------------

/// Task L (Low):     period=200, deadline=200, wcet=40, offset=0
/// Task H (High):    period=60,  deadline=60,  wcet=20, offset=10
/// Task M (Medium):  period=100, deadline=100, wcet=30, offset=15
fn build_tasks() -> Vec<Task> {
    let task_l = Task::new(
        0, "L", 3, 200, 200,
        vec![
            Segment::Compute(5),
            Segment::CriticalSection { duration: 20, mutex_id: 0 },
            Segment::Compute(15),
        ],
        0,
    );

    let task_h = Task::new(
        1, "H", 1, 60, 60,
        vec![
            Segment::Compute(5),
            Segment::CriticalSection { duration: 5, mutex_id: 0 },
            Segment::Compute(10),
        ],
        10,
    );

    let task_m = Task::new(
        2, "M", 2, 100, 100,
        vec![Segment::Compute(30)],
        15,
    );

    vec![task_l, task_h, task_m]
}

fn build_tasks_with_jitter(jitter_pct: f64, seed: u64) -> Vec<Task> {
    let mut rng: StdRng = SeedableRng::seed_from_u64(seed);
    let base = build_tasks();
    base.into_iter()
        .map(|t| t.with_jitter(jitter_pct, &mut || rng.gen::<f64>()))
        .collect()
}

// ---------------------------------------------------------------------------
// Single run
// ---------------------------------------------------------------------------

pub fn run_single(pi_enabled: bool, sim_duration: u32) -> SingleRunResult {
    run_single_with_jitter(pi_enabled, sim_duration, 0.0, 0)
}

pub fn run_single_with_jitter(
    pi_enabled: bool,
    sim_duration: u32,
    jitter_pct: f64,
    seed: u64,
) -> SingleRunResult {
    let tasks = if jitter_pct > 0.0 {
        build_tasks_with_jitter(jitter_pct, seed)
    } else {
        build_tasks()
    };

    let mutex = PiMutex::new(0, pi_enabled);
    let mut kernel = Kernel::new(tasks, vec![mutex], sim_duration);
    kernel.run();

    let events: Vec<Event> = kernel.events.clone();
    let tick_runner: Vec<Option<usize>> = kernel.tick_runner.clone();
    let tasks = &kernel.tasks;

    // Measure H's inversion duration: time from Blocked to Unblocked
    let mut h_block_time: Option<u32> = None;
    let mut h_unblock_time: Option<u32> = None;
    for ev in &events {
        if ev.task_id == 1 {
            match &ev.event_type {
                EventType::Blocked(_) => h_block_time = Some(ev.time),
                EventType::Unblocked(_) => h_unblock_time = Some(ev.time),
                _ => {}
            }
        }
    }
    let h_inversion_duration = match (h_block_time, h_unblock_time) {
        (Some(b), Some(u)) => Some(u - b),
        _ => None,
    };

    let h_task = &tasks[1];
    let h_response_time = h_task.response_times.first().copied();
    let h_deadline_missed = h_task.deadline_misses > 0;

    let total_deadline_misses: u32 = tasks.iter().map(|t| t.deadline_misses).sum();

    let per_task_misses: Vec<(String, u32)> = tasks
        .iter()
        .map(|t| (t.name.clone(), t.deadline_misses))
        .collect();

    let per_task_avg_response: Vec<(String, f64)> = tasks
        .iter()
        .map(|t| {
            let avg = if t.response_times.is_empty() {
                0.0
            } else {
                t.response_times.iter().sum::<u32>() as f64 / t.response_times.len() as f64
            };
            (t.name.clone(), avg)
        })
        .collect();

    SingleRunResult {
        pi_enabled,
        h_inversion_duration,
        h_response_time,
        h_deadline_missed,
        total_deadline_misses,
        per_task_misses,
        per_task_avg_response,
        events,
        tick_runner,
    }
}

// ---------------------------------------------------------------------------
// Batch runs
// ---------------------------------------------------------------------------

pub fn run_batch(n_runs: usize, pi_enabled: bool, sim_duration: u32) -> BatchResult {
    run_batch_with_jitter(n_runs, pi_enabled, sim_duration, 0.0)
}

pub fn run_batch_with_jitter(
    n_runs: usize,
    pi_enabled: bool,
    sim_duration: u32,
    jitter_pct: f64,
) -> BatchResult {
    let mut h_inversion_durations = Vec::with_capacity(n_runs);
    let mut h_response_times = Vec::with_capacity(n_runs);
    let mut total_deadline_misses = Vec::with_capacity(n_runs);
    let mut first_run_events = Vec::new();
    let mut first_run_tick_runner = Vec::new();
    let mut h_deadline_miss_count = 0u32;

    for i in 0..n_runs {
        let seed = if jitter_pct > 0.0 { (i + 1) as u64 * 7919 } else { 0 };
        let result = run_single_with_jitter(pi_enabled, sim_duration, jitter_pct, seed);

        if i == 0 {
            first_run_events = result.events;
            first_run_tick_runner = result.tick_runner;
        }

        h_inversion_durations.push(result.h_inversion_duration);
        h_response_times.push(result.h_response_time);
        total_deadline_misses.push(result.total_deadline_misses);
        if result.h_deadline_missed {
            h_deadline_miss_count += 1;
        }
    }

    BatchResult {
        pi_enabled,
        n_runs,
        h_inversion_durations,
        h_response_times,
        h_deadline_miss_count,
        total_deadline_misses,
        first_run_events,
        first_run_tick_runner,
    }
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

const TASK_NAMES: [&str; 3] = ["L", "H", "M"];

pub fn print_timeline(tick_runner: &[Option<usize>], max_ticks: usize) {
    println!("\n  Execution Timeline:");
    println!("  {}", "-".repeat(72));

    // Group consecutive ticks by task
    let limit = max_ticks.min(tick_runner.len());
    let mut groups: Vec<(String, u32, u32)> = Vec::new();
    for tick in 0..limit {
        let name = match tick_runner[tick] {
            Some(id) => TASK_NAMES.get(id).unwrap_or(&"?").to_string(),
            None => "-".to_string(),
        };
        if let Some(last) = groups.last_mut() {
            if last.0 == name && last.2 + 1 == tick as u32 {
                last.2 = tick as u32;
            } else {
                groups.push((name, tick as u32, tick as u32));
            }
        } else {
            groups.push((name, tick as u32, tick as u32));
        }
    }

    for (task, start, end) in &groups {
        let bar_len = (*end - *start + 1) as usize;
        let bar: String = match task.as_str() {
            "H" => "H".repeat(bar_len),
            "M" => "M".repeat(bar_len),
            "L" => "L".repeat(bar_len),
            _ => ".".repeat(bar_len),
        };
        println!("  t={:>3}-{:<3} {} ({})", start, end, bar, task);
    }
    println!("  {}", "-".repeat(72));
}

pub fn print_events(events: &[Event], max_events: usize) {
    println!("\n  Key Events:");
    println!("  {:>5}  {:>4}  {:>14}  {}", "Time", "Task", "Event", "Detail");
    println!("  {}", "-".repeat(60));

    let mut count = 0;
    for ev in events {
        // Skip SCHEDULED events (too many, one per tick)
        if matches!(ev.event_type, EventType::Scheduled) {
            continue;
        }
        if count >= max_events {
            println!("  ... ({} more events)", events.len() - max_events);
            break;
        }
        let name = TASK_NAMES.get(ev.task_id).unwrap_or(&"?");
        let (ev_name, detail) = format_event(&ev.event_type);
        println!("  {:>5}  {:>4}  {:>14}  {}", ev.time, name, ev_name, detail);
        count += 1;
    }
}

fn format_event(et: &EventType) -> (&'static str, String) {
    match et {
        EventType::Released => ("RELEASED", String::new()),
        EventType::Scheduled => ("SCHEDULED", String::new()),
        EventType::Preempted => ("PREEMPTED", String::new()),
        EventType::Blocked(mid) => ("BLOCKED", format!("mutex={}", mid)),
        EventType::Unblocked(mid) => ("UNBLOCKED", format!("mutex={}", mid)),
        EventType::MutexAcquired(mid) => ("LOCK_ACQ", format!("mutex={}", mid)),
        EventType::MutexReleased(mid) => ("LOCK_REL", format!("mutex={}", mid)),
        EventType::JobCompleted { response_time } => {
            ("JOB_DONE", format!("resp_time={}", response_time))
        }
        EventType::DeadlineMissed { deadline, completed_at } => (
            "DEADLINE_MISS",
            format!("deadline={}, completed={}", deadline, completed_at),
        ),
        EventType::PriorityInherited { new_effective_deadline } => (
            "PI_BOOST",
            format!("eff_deadline={}", new_effective_deadline),
        ),
        EventType::PriorityRestored { original_deadline } => (
            "PI_RESTORE",
            format!("deadline={}", original_deadline),
        ),
    }
}

pub fn print_batch_summary(label: &str, result: &BatchResult) {
    println!("\n{}", "=".repeat(70));
    println!("  {} (PI {})", label, if result.pi_enabled { "ON" } else { "OFF" });
    println!("  Runs: {}", result.n_runs);
    println!("{}", "=".repeat(70));

    if let Some(stats) = result.h_inversion_stats() {
        println!("  H Inversion Duration: mean={:.2}  std_dev={:.4}  min={:.0}  max={:.0}",
            stats.mean, stats.std_dev, stats.min, stats.max);
    } else {
        println!("  H Inversion Duration: N/A (no inversion detected)");
    }

    if let Some(stats) = result.h_response_stats() {
        println!("  H Response Time:      mean={:.2}  std_dev={:.4}  min={:.0}  max={:.0}",
            stats.mean, stats.std_dev, stats.min, stats.max);
    }

    if let Some(stats) = result.total_misses_stats() {
        println!("  Total Deadline Misses: mean={:.2}  std_dev={:.4}  min={:.0}  max={:.0}",
            stats.mean, stats.std_dev, stats.min, stats.max);
    }

    println!("  H Deadline Miss Rate:  {}/{} runs ({:.1}%)",
        result.h_deadline_miss_count, result.n_runs,
        result.h_deadline_miss_count as f64 / result.n_runs as f64 * 100.0);
}

pub fn print_comparison(no_pi: &BatchResult, with_pi: &BatchResult) {
    println!("\n{}", "=".repeat(70));
    println!("  COMPARISON: PI OFF vs PI ON");
    println!("{}", "=".repeat(70));
    println!("  {:>25}  {:>12}  {:>12}", "Metric", "PI OFF", "PI ON");
    println!("  {}", "-".repeat(52));

    let fmt = |s: Option<Stats>| -> String {
        match s {
            Some(st) => format!("{:.1} +/- {:.2}", st.mean, st.std_dev),
            None => "N/A".into(),
        }
    };

    println!("  {:>25}  {:>12}  {:>12}",
        "H Inversion Duration",
        fmt(no_pi.h_inversion_stats()),
        fmt(with_pi.h_inversion_stats()));

    println!("  {:>25}  {:>12}  {:>12}",
        "H Response Time",
        fmt(no_pi.h_response_stats()),
        fmt(with_pi.h_response_stats()));

    println!("  {:>25}  {:>12}  {:>12}",
        "Total Deadline Misses",
        fmt(no_pi.total_misses_stats()),
        fmt(with_pi.total_misses_stats()));

    println!("  {:>25}  {:>12}  {:>12}",
        "H Deadline Miss Rate",
        format!("{:.0}%", no_pi.h_deadline_miss_count as f64 / no_pi.n_runs as f64 * 100.0),
        format!("{:.0}%", with_pi.h_deadline_miss_count as f64 / with_pi.n_runs as f64 * 100.0));

    println!();
}

use crate::event::{Event, EventType};
use crate::mutex::PiMutex;
use crate::scheduler::EdfScheduler;
use crate::task::{Task, TaskState};

/// Tick-based discrete-event RTOS kernel simulator.
pub struct Kernel {
    pub tasks: Vec<Task>,
    pub mutexes: Vec<PiMutex>,
    pub current_time: u32,
    pub sim_duration: u32,
    pub events: Vec<Event>,
    /// Which task was running at each tick (for timeline).
    pub tick_runner: Vec<Option<usize>>,
    running_task_id: Option<usize>,
}

impl Kernel {
    pub fn new(tasks: Vec<Task>, mutexes: Vec<PiMutex>, sim_duration: u32) -> Self {
        Kernel {
            tasks,
            mutexes,
            current_time: 0,
            sim_duration,
            events: Vec::new(),
            tick_runner: Vec::with_capacity(sim_duration as usize),
            running_task_id: None,
        }
    }

    /// Run the simulation to completion.
    pub fn run(&mut self) {
        while self.current_time < self.sim_duration {
            self.tick();
            self.current_time += 1;
        }
    }

    fn tick(&mut self) {
        let t = self.current_time;

        // 0. Reset currently running task to Ready for rescheduling
        let prev_running = self.running_task_id;
        if let Some(cur) = self.running_task_id {
            if self.tasks[cur].state == TaskState::Running {
                self.tasks[cur].state = TaskState::Ready;
            }
        }

        // 1. Release new periodic jobs
        for i in 0..self.tasks.len() {
            if self.tasks[i].next_release == t {
                // If previous job not done, count as deadline miss
                if self.tasks[i].state != TaskState::Suspended {
                    self.tasks[i].deadline_misses += 1;
                    if let Some(mux_id) = self.tasks[i].held_mutex {
                        self.mutexes[mux_id].unlock(
                            i,
                            &mut self.tasks,
                            &mut self.events,
                            t,
                        );
                    }
                    self.tasks[i].state = TaskState::Suspended;
                    let rt = t - self.tasks[i].current_job_release;
                    self.tasks[i].response_times.push(rt);
                    self.tasks[i].jobs_completed += 1;
                    self.events.push(Event::new(
                        t,
                        i,
                        EventType::DeadlineMissed {
                            deadline: self.tasks[i].absolute_deadline,
                            completed_at: t,
                        },
                    ));
                }
                self.tasks[i].release_job(t);
                self.events.push(Event::new(t, i, EventType::Released));

                // If first segment is a critical section, try to acquire mutex
                let first_mutex = self.tasks[i].current_segment_mutex();
                if let Some(mutex_id) = first_mutex {
                    if self.tasks[i].held_mutex.is_none() {
                        self.mutexes[mutex_id].try_lock(
                            i,
                            &mut self.tasks,
                            &mut self.events,
                            t,
                        );
                    }
                }
            }
        }

        // 2. Schedule: pick the ready task with earliest effective deadline
        let next = EdfScheduler::pick_next(&self.tasks);

        if let Some(next_id) = next {
            // Log preemption if different task chosen and prev was still Running
            if let Some(prev) = prev_running {
                if prev != next_id && self.tasks[prev].state == TaskState::Ready {
                    self.events.push(Event::new(t, prev, EventType::Preempted));
                }
            }

            self.tasks[next_id].state = TaskState::Running;
            self.running_task_id = Some(next_id);
            self.events.push(Event::new(t, next_id, EventType::Scheduled));

            // 3. Execute one tick
            self.tasks[next_id].segment_remaining -= 1;

            // 4. Check segment completion
            if self.tasks[next_id].segment_remaining == 0 {
                self.handle_segment_done(next_id);
            }

            self.tick_runner.push(Some(next_id));
        } else {
            // No task to run — idle tick
            self.running_task_id = None;
            self.tick_runner.push(None);
        }
    }

    /// Handle completion of the current segment for a task.
    fn handle_segment_done(&mut self, task_id: usize) {
        // Step 1: Get current segment's mutex (if any) — returns Copy value
        let cur_mutex = self.tasks[task_id].current_segment_mutex();

        // Step 2: Release mutex if we were in a critical section
        if let Some(mutex_id) = cur_mutex {
            self.mutexes[mutex_id].unlock(
                task_id,
                &mut self.tasks,
                &mut self.events,
                self.current_time,
            );
        }

        // Step 3: Advance to next segment
        self.tasks[task_id].advance_to_next_segment();

        // Step 4: Check if job is complete
        if self.tasks[task_id].is_job_complete() {
            self.handle_job_complete(task_id);
            return;
        }

        // Step 5: If new segment needs a mutex, try to acquire
        let next_mutex = self.tasks[task_id].current_segment_mutex();
        if let Some(mutex_id) = next_mutex {
            self.mutexes[mutex_id].try_lock(
                task_id,
                &mut self.tasks,
                &mut self.events,
                self.current_time,
            );
        }
    }

    /// Handle job completion for a task.
    fn handle_job_complete(&mut self, task_id: usize) {
        let completion_time = self.current_time;
        let deadline = self.tasks[task_id].absolute_deadline;
        let release_time = self.tasks[task_id].current_job_release;
        let response_time = completion_time + 1 - release_time;

        self.tasks[task_id].response_times.push(response_time);
        self.tasks[task_id].jobs_completed += 1;
        self.tasks[task_id].state = TaskState::Suspended;

        if completion_time + 1 > deadline {
            self.tasks[task_id].deadline_misses += 1;
            self.events.push(Event::new(
                completion_time,
                task_id,
                EventType::DeadlineMissed {
                    deadline,
                    completed_at: completion_time + 1,
                },
            ));
        }

        self.events.push(Event::new(
            completion_time,
            task_id,
            EventType::JobCompleted { response_time },
        ));

        if self.running_task_id == Some(task_id) {
            self.running_task_id = None;
        }
    }

    pub fn task_name(&self, id: usize) -> &str {
        &self.tasks[id].name
    }
}

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaskState {
    Suspended,
    Ready,
    Running,
    Blocked,
}

impl fmt::Display for TaskState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TaskState::Suspended => write!(f, "SUSPENDED"),
            TaskState::Ready => write!(f, "READY"),
            TaskState::Running => write!(f, "RUNNING"),
            TaskState::Blocked => write!(f, "BLOCKED"),
        }
    }
}

/// A segment of a task's job. Each job is a sequence of segments executed in order.
#[derive(Debug, Clone)]
pub enum Segment {
    /// Regular computation (duration in ticks).
    Compute(u32),
    /// Critical section: acquires mutex at segment start, releases at segment end.
    CriticalSection { duration: u32, mutex_id: usize },
}

/// A real-time periodic task.
#[derive(Debug, Clone)]
pub struct Task {
    pub id: usize,
    pub name: String,
    /// Static base priority. Lower value = higher priority. Used for PI reference.
    pub base_priority: u32,
    /// Period of job releases (ticks).
    pub period: u32,
    /// Relative deadline from job release (ticks).
    pub relative_deadline: u32,
    /// Job template: sequence of segments executed each period.
    pub segments: Vec<Segment>,

    // --- Dynamic state ---
    pub state: TaskState,
    /// Absolute deadline of current job instance.
    pub absolute_deadline: u32,
    /// Effective deadline for EDF scheduling. May be reduced by priority inheritance.
    pub effective_deadline: u32,
    /// Next periodic release time.
    pub next_release: u32,
    /// Index of current segment being executed.
    pub current_segment_idx: usize,
    /// Remaining ticks in current segment.
    pub segment_remaining: u32,
    /// Mutex currently held by this task.
    pub held_mutex: Option<usize>,

    // --- Metrics ---
    pub jobs_completed: u32,
    pub deadline_misses: u32,
    pub current_job_release: u32,
    pub response_times: Vec<u32>,
    /// Tick when task became blocked (for measuring inversion duration).
    pub blocked_at: Option<u32>,
}

impl Task {
    pub fn new(
        id: usize,
        name: &str,
        base_priority: u32,
        period: u32,
        relative_deadline: u32,
        segments: Vec<Segment>,
        first_release: u32,
    ) -> Self {
        Task {
            id,
            name: name.to_string(),
            base_priority,
            period,
            relative_deadline,
            segments,
            state: TaskState::Suspended,
            absolute_deadline: u32::MAX,
            effective_deadline: u32::MAX,
            next_release: first_release,
            current_segment_idx: 0,
            segment_remaining: 0,
            held_mutex: None,
            jobs_completed: 0,
            deadline_misses: 0,
            current_job_release: 0,
            response_times: Vec::new(),
            blocked_at: None,
        }
    }

    pub fn wcet(&self) -> u32 {
        self.segments
            .iter()
            .map(|s| match s {
                Segment::Compute(d) => *d,
                Segment::CriticalSection { duration, .. } => *duration,
            })
            .sum()
    }

    /// Release a new job instance at the given time.
    pub fn release_job(&mut self, time: u32) {
        self.state = TaskState::Ready;
        self.absolute_deadline = time + self.relative_deadline;
        self.effective_deadline = self.absolute_deadline;
        self.current_segment_idx = 0;
        self.segment_remaining = match &self.segments[0] {
            Segment::Compute(d) => *d,
            Segment::CriticalSection { duration, .. } => *duration,
        };
        self.held_mutex = None;
        self.current_job_release = time;
        self.blocked_at = None;
        self.next_release += self.period;
    }

    /// Returns true if all segments of the current job have been completed.
    pub fn is_job_complete(&self) -> bool {
        self.current_segment_idx >= self.segments.len()
    }

    /// Advance to the next segment. Returns the next segment reference, or None if job is done.
    pub fn advance_to_next_segment(&mut self) -> Option<&Segment> {
        self.current_segment_idx += 1;
        if self.current_segment_idx < self.segments.len() {
            let segment = &self.segments[self.current_segment_idx];
            self.segment_remaining = match segment {
                Segment::Compute(d) => *d,
                Segment::CriticalSection { duration, .. } => *duration,
            };
            Some(segment)
        } else {
            None
        }
    }

    /// Returns the mutex_id if the current segment is a critical section.
    pub fn current_segment_mutex(&self) -> Option<usize> {
        if self.current_segment_idx < self.segments.len() {
            match &self.segments[self.current_segment_idx] {
                Segment::CriticalSection { mutex_id, .. } => Some(*mutex_id),
                _ => None,
            }
        } else {
            None
        }
    }

    /// Apply jitter to segment durations. Returns a new Task with varied durations.
    pub fn with_jitter(&self, jitter_pct: f64, rng: &mut impl FnMut() -> f64) -> Self {
        let mut task = self.clone();
        task.segments = task
            .segments
            .iter()
            .map(|s| match s {
                Segment::Compute(d) => {
                    let jittered = apply_jitter(*d, jitter_pct, rng);
                    Segment::Compute(jittered)
                }
                Segment::CriticalSection { duration, mutex_id } => {
                    let jittered = apply_jitter(*duration, jitter_pct, rng);
                    Segment::CriticalSection {
                        duration: jittered,
                        mutex_id: *mutex_id,
                    }
                }
            })
            .collect();
        task
    }
}

fn apply_jitter(value: u32, pct: f64, rng: &mut impl FnMut() -> f64) -> u32 {
    let factor = 1.0 + (rng() * 2.0 - 1.0) * pct;
    ((value as f64) * factor).round().max(1.0) as u32
}

