1	use crate::event::{Event, EventType};
2	use crate::mutex::PiMutex;
3	use crate::scheduler::EdfScheduler;
4	use crate::task::{Task, TaskState};
5	
6	/// Tick-based discrete-event RTOS kernel simulator.
7	pub struct Kernel {
8	    pub tasks: Vec<Task>,
9	    pub mutexes: Vec<PiMutex>,
10	    pub current_time: u32,
11	    pub sim_duration: u32,
12	    pub events: Vec<Event>,
13	    /// Which task was running at each tick (for timeline).
14	    pub tick_runner: Vec<Option<usize>>,
15	    running_task_id: Option<usize>,
16	}
17	
18	impl Kernel {
19	    pub fn new(tasks: Vec<Task>, mutexes: Vec<PiMutex>, sim_duration: u32) -> Self {
20	        Kernel {
21	            tasks,
22	            mutexes,
23	            current_time: 0,
24	            sim_duration,
25	            events: Vec::new(),
26	            tick_runner: Vec::with_capacity(sim_duration as usize),
27	            running_task_id: None,
28	        }
29	    }
30	
31	    /// Run the simulation to completion.
32	    pub fn run(&mut self) {
33	        while self.current_time < self.sim_duration {
34	            self.tick();
35	            self.current_time += 1;
36	        }
37	    }
38	
39	    fn tick(&mut self) {
40	        let t = self.current_time;
41	
42	        // 0. Reset currently running task to Ready for rescheduling
43	        let prev_running = self.running_task_id;
44	        if let Some(cur) = self.running_task_id {
45	            if self.tasks[cur].state == TaskState::Running {
46	                self.tasks[cur].state = TaskState::Ready;
47	            }
48	        }
49	
50	        // 1. Release new periodic jobs
51	        for i in 0..self.tasks.len() {
52	            if self.tasks[i].next_release == t {
53	                // If previous job not done, count as deadline miss
54	                if self.tasks[i].state != TaskState::Suspended {
55	                    self.tasks[i].deadline_misses += 1;
56	                    if let Some(mux_id) = self.tasks[i].held_mutex {
57	                        self.mutexes[mux_id].unlock(
58	                            i,
59	                            &mut self.tasks,
60	                            &mut self.events,
61	                            t,
62	                        );
63	                    }
64	                    self.tasks[i].state = TaskState::Suspended;
65	                    let rt = t - self.tasks[i].current_job_release;
66	                    self.tasks[i].response_times.push(rt);
67	                    self.tasks[i].jobs_completed += 1;
68	                    self.events.push(Event::new(
69	                        t,
70	                        i,
71	                        EventType::DeadlineMissed {
72	                            deadline: self.tasks[i].absolute_deadline,
73	                            completed_at: t,
74	                        },
75	                    ));
76	                }
77	                self.tasks[i].release_job(t);
78	                self.events.push(Event::new(t, i, EventType::Released));
79	
80	                // If first segment is a critical section, try to acquire mutex
81	                let first_mutex = self.tasks[i].current_segment_mutex();
82	                if let Some(mutex_id) = first_mutex {
83	                    if self.tasks[i].held_mutex.is_none() {
84	                        self.mutexes[mutex_id].try_lock(
85	                            i,
86	                            &mut self.tasks,
87	                            &mut self.events,
88	                            t,
89	                        );
90	                    }
91	                }
92	            }
93	        }
94	
95	        // 2. Schedule: pick the ready task with earliest effective deadline
96	        let next = EdfScheduler::pick_next(&self.tasks);
97	
98	        if let Some(next_id) = next {
99	            // Log preemption if different task chosen and prev was still Running
100	            if let Some(prev) = prev_running {
101	                if prev != next_id && self.tasks[prev].state == TaskState::Ready {
102	                    self.events.push(Event::new(t, prev, EventType::Preempted));
103	                }
104	            }
105	
106	            self.tasks[next_id].state = TaskState::Running;
107	            self.running_task_id = Some(next_id);
108	            self.events.push(Event::new(t, next_id, EventType::Scheduled));
109	
110	            // 3. Execute one tick
111	            self.tasks[next_id].segment_remaining -= 1;
112	
113	            // 4. Check segment completion
114	            if self.tasks[next_id].segment_remaining == 0 {
115	                self.handle_segment_done(next_id);
116	            }
117	
118	            self.tick_runner.push(Some(next_id));
119	        } else {
120	            // No task to run — idle tick
121	            self.running_task_id = None;
122	            self.tick_runner.push(None);
123	        }
124	    }
125	
126	    /// Handle completion of the current segment for a task.
127	    fn handle_segment_done(&mut self, task_id: usize) {
128	        // Step 1: Get current segment's mutex (if any) — returns Copy value
129	        let cur_mutex = self.tasks[task_id].current_segment_mutex();
130	
131	        // Step 2: Release mutex if we were in a critical section
132	        if let Some(mutex_id) = cur_mutex {
133	            self.mutexes[mutex_id].unlock(
134	                task_id,
135	                &mut self.tasks,
136	                &mut self.events,
137	                self.current_time,
138	            );
139	        }
140	
141	        // Step 3: Advance to next segment
142	        self.tasks[task_id].advance_to_next_segment();
143	
144	        // Step 4: Check if job is complete
145	        if self.tasks[task_id].is_job_complete() {
146	            self.handle_job_complete(task_id);
147	            return;
148	        }
149	
150	        // Step 5: If new segment needs a mutex, try to acquire
151	        let next_mutex = self.tasks[task_id].current_segment_mutex();
152	        if let Some(mutex_id) = next_mutex {
153	            self.mutexes[mutex_id].try_lock(
154	                task_id,
155	                &mut self.tasks,
156	                &mut self.events,
157	                self.current_time,
158	            );
159	        }
160	    }
161	
162	    /// Handle job completion for a task.
163	    fn handle_job_complete(&mut self, task_id: usize) {
164	        let completion_time = self.current_time;
165	        let deadline = self.tasks[task_id].absolute_deadline;
166	        let release_time = self.tasks[task_id].current_job_release;
167	        let response_time = completion_time + 1 - release_time;
168	
169	        self.tasks[task_id].response_times.push(response_time);
170	        self.tasks[task_id].jobs_completed += 1;
171	        self.tasks[task_id].state = TaskState::Suspended;
172	
173	        if completion_time + 1 > deadline {
174	            self.tasks[task_id].deadline_misses += 1;
175	            self.events.push(Event::new(
176	                completion_time,
177	                task_id,
178	                EventType::DeadlineMissed {
179	                    deadline,
180	                    completed_at: completion_time + 1,
181	                },
182	            ));
183	        }
184	
185	        self.events.push(Event::new(
186	            completion_time,
187	            task_id,
188	            EventType::JobCompleted { response_time },
189	        ));
190	
191	        if self.running_task_id == Some(task_id) {
192	            self.running_task_id = None;
193	        }
194	    }
195	
196	    pub fn task_name(&self, id: usize) -> &str {
197	        &self.tasks[id].name
198	    }
199	}
