160	    pub fn with_jitter(&self, jitter_pct: f64, rng: &mut impl FnMut() -> f64) -> Self {
161	        let mut task = self.clone();
162	        task.segments = task
163	            .segments
164	            .iter()
165	            .map(|s| match s {
166	                Segment::Compute(d) => {
167	                    let jittered = apply_jitter(*d, jitter_pct, rng);
168	                    Segment::Compute(jittered)
169	                }
170	                Segment::CriticalSection { duration, mutex_id } => {
171	                    let jittered = apply_jitter(*duration, jitter_pct, rng);
172	                    Segment::CriticalSection {
173	                        duration: jittered,
174	                        mutex_id: *mutex_id,
175	                    }
176	                }
177	            })
178	            .collect();
179	        task
180	    }
181	}
