183	fn apply_jitter(value: u32, pct: f64, rng: &mut impl FnMut() -> f64) -> u32 {
184	    let factor = 1.0 + (rng() * 2.0 - 1.0) * pct;
185	    ((value as f64) * factor).round().max(1.0) as u32
186	}
